kmarkSchema.safeParse(input);\n    expect(result.success).toBe(true);\n    if (result.success) {\n      expect(result.data).toEqual(input);\n    }\n  });\n\n  it('should accept valid input with only required url field', () => {\n    const input = {\n      url: 'https://example.com',\n    };\n    const result = createBookmarkSchema.safeParse(input);\n    expect(result.success).toBe(true);\n    if (result.success) {\n      expect(result.data.url).toBe('https://example.com');\n      expect(result.data.title).toBeUndefined();\n      expect(result.data.tags).toBeUndefined();\n    }\n  });\n\n  it('should reject missing url', () => {\n    const input = {\n      title: 'No URL Provided',\n      tags: ['test'],\n    };\n    const result = createBookmarkSchema.safeParse(input);\n    expect(result.success).toBe(false);\n    if (!result.success) {\n      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));\n      expect(urlError).toBeDefined();\n    }\n  });\n\n  it('should reject url that is too long (> 2048 characters)', () => {\n    const longPath = 'a'.repeat(2040);\n    const input = {\n      url: `https://example.com/${longPath}`,\n    };\n    expect(input.url.length).toBeGreaterThan(2048);\n    const result = createBookmarkSchema.safeParse(input);\n    expect(result.success).toBe(false);\n    if (!result.success) {\n      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));\n      expect(urlError).toBeDefined();\n    }\n  });\n\n  it('should reject more than 10 tags', () => {\n    const input = {\n      url: 'https://example.com',\n      tags: Array.from({ length: 11 }, (_, i) => `tag-${i}`),\n    };\n    const result = createBookmarkSchema.safeParse(input);\n    expect(result.success).toBe(false);\n    if (!result.success) {\n      const tagError = result.error.issues.find((issue) => issue.path.includes('tags'));\n      expect(tagError).toBeDefined();\n    }\n  });\n\n  it('should reject a tag that is too long (