import express from 'express';
import { bookmarksRouter } from './routes/bookmarks.js';
import { errorHandler } from './middleware/error-handler.js';

export const app = express();

app.use(express.json());

app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

app.use('/api/v1/bookmarks', bookmarksRouter);

app.use(errorHandler);

import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema', () => {
  it('should accept valid inputs with all fields', () => {
    const input = {
      url: 'https://example.com/articles/typescript',
      title: 'TypeScript Guide',
      tags: ['typescript', 'node', 'express'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data).toEqual(input);
    }
  });

  it('should accept valid input with only required url field', () => {
    const input = {
      url: 'https://example.com',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe('https://example.com');
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should reject missing url', () => {
    const input = {
      title: 'No URL Provided',
      tags: ['test'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should reject url that is too long (> 2048 characters)', () => {
    const longPath = 'a'.repeat(2040);
    const input = {
      url: `https://example.com/${longPath}`,
    };
    expect(input.url.length).toBeGreaterThan(2048);
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const urlError = result.error.issues.find((issue) => issue.path.includes('url'));
      expect(urlError).toBeDefined();
    }
  });

  it('should reject more than 10 tags', () => {
    const input = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_, i) => `tag-${i}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagError = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagError).toBeDefined();
    }
  });

  it('should reject a tag that is too long (> 50 characters)', () => {
    const input = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const tagError = result.error.issues.find((issue) => issue.path.includes('tags'));
      expect(tagError).toBeDefined();
    }
  });

  it('should reject invalid url format', () => {
    const input = {
      url: 'not-a-valid-url',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should reject title exceeding 200 characters', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with id, createdAt, and input properties', () => {
      const input = {
        url: 'https://example.com/guide',
        title: 'Example Guide',
        tags: ['guide', 'test'],
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.id.length).toBeGreaterThan(0);
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBe(input.title);
      expect(bookmark.tags).toEqual(input.tags);
      expect(bookmark.createdAt).toBeDefined();
      expect(Number.isNaN(Date.parse(bookmark.createdAt))).toBe(false);
    });

    it('should create a bookmark without optional fields', () => {
      const input = {
        url: 'https://example.com/minimal',
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when creating a bookmark with an existing URL', () => {
      const url = 'https://example.com/duplicate';
      service.create({ url, title: 'First' });

      expect(() => {
        service.create({ url, title: 'Second' });
      }).toThrow(DuplicateBookmarkError);
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id', () => {
      const created = service.create({
        url: 'https://example.com/item',
        title: 'Item',
      });

      const retrieved = service.getById(created.id);
      expect(retrieved).toEqual(created);
    });

    it('should return undefined when retrieving a non-existent id', () => {
      const result = service.getById('non-existent-id');
      expect(result).toBeUndefined();
    });

    it('should retrieve all bookmarks sorted by createdAt descending', async () => {
      const first = service.create({ url: 'https://example.com/first' });
      await new Promise<void>((resolve) => setTimeout(resolve, 5));
      const second = service.create({ url: 'https://example.com/second' });

      const all = service.getAll();
      expect(all.length).toBe(2);
      expect(all[0].id).toBe(second.id);
      expect(all[1].id).toBe(first.id);
    });
  });
});

