function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

