import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService, type Bookmark } from '../src/services/bookmark-service.js';

describe('PATCH /api/v1/bookmarks/:id', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  it('should update title only while keeping tags and url unchanged', async () => {
    const bookmark = bookmarkService.create({
      url: 'https://example.com/initial',
      title: 'Original Title',
      tags: ['tag1', 'tag2'],
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({ title: 'Updated Title' })
      .set('Accept', 'application/json');

    expect(response.status).toBe(200);
    const body = response.body as Bookmark;
    expect(body.id).toBe(bookmark.id);
    expect(body.title).toBe('Updated Title');
    expect(body.tags).toEqual(['tag1', 'tag2']);
    expect(body.url).toBe(bookmark.url);
    expect(body.createdAt).toBe(bookmark.createdAt);

    // Verify persisted state in service
    const fetched = bookmarkService.getById(bookmark.id);
    expect(fetched?.title).toBe('Updated Title');
  });

  it('should update tags only while keeping title and url unchanged', async () => {
    const bookmark = bookmarkService.create({
      url: 'https://example.com/initial',
      title: 'Original Title',
      tags: ['original-tag'],
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({ tags: ['new-tag1', 'new-tag2'] })
      .set('Accept', 'application/json');

    expect(response.status).toBe(200);
    const body = response.body as Bookmark;
    expect(body.id).toBe(bookmark.id);
    expect(body.title).toBe('Original Title');
    expect(body.tags).toEqual(['new-tag1', 'new-tag2']);
    expect(body.url).toBe(bookmark.url);
    expect(body.createdAt).toBe(bookmark.createdAt);
  });

  it('should update both title and tags while keeping url unchanged', async () => {
    const bookmark = bookmarkService.create({
      url: 'https://example.com/initial',
      title: 'Original Title',
      tags: ['old-tag'],
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({
        title: 'New Title',
        tags: ['updated-tag'],
      })
      .set('Accept', 'application/json');

    expect(response.status).toBe(200);
    const body = response.body as Bookmark;
    expect(body.id).toBe(bookmark.id);
    expect(body.title).toBe('New Title');
    expect(body.tags).toEqual(['updated-tag']);
    expect(body.url).toBe(bookmark.url);
    expect(body.createdAt).toBe(bookmark.createdAt);
  });

  it('should return 404 when updating non-existent bookmark ID', async () => {
    const nonExistentId = '00000000-0000-0000-0000-000000000000';

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${nonExistentId}`)
      .send({ title: 'New Title' })
      .set('Accept', 'application/json');

    expect(response.status).toBe(404);
    const body = response.body as { error: string };
    expect(body.error).toBe('Bookmark not found');
  });

  it('should reject URL change attempt with 400 and preserve original URL', async () => {
    const originalUrl = 'https://example.com/immutable';
    const bookmark = bookmarkService.create({
      url: originalUrl,
      title: 'Original Title',
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({ url: 'https://example.com/hacked' })
      .set('Accept', 'application/json');

    expect(response.status).toBe(400);
    const body = response.body as { error: string };
    expect(body.error).toContain('immutable');

    // Confirm that the bookmark in storage was not changed
    const fetched = bookmarkService.getById(bookmark.id);
    expect(fetched?.url).toBe(originalUrl);
  });

  it('should reject URL change attempt even if accompanied by a valid title update', async () => {
    const originalUrl = 'https://example.com/immutable-2';
    const originalTitle = 'Original Title';
    const bookmark = bookmarkService.create({
      url: originalUrl,
      title: originalTitle,
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({
        title: 'Sneaky Update',
        url: 'https://example.com/changed',
      })
      .set('Accept', 'application/json');

    expect(response.status).toBe(400);

    const fetched = bookmarkService.getById(bookmark.id);
    expect(fetched?.url).toBe(originalUrl);
    expect(fetched?.title).toBe(originalTitle);
  });

  it('should return 422 validation error when title exceeds 200 characters', async () => {
    const bookmark = bookmarkService.create({
      url: 'https://example.com/valid',
      title: 'Valid Title',
    });

    const response = await request(app)
      .patch(`/api/v1/bookmarks/${bookmark.id}`)
      .send({ title: 'a'.repeat(201) })
      .set('Accept', 'application/json');

    expect(response.status).toBe(422);
    const body = response.body as { error: string; details: unknown[] };
    expect(body.error).toBe('Validation failed');
    expect(Array.isArray(body.details)).toBe(true);
  });
});

