=== SERVICE EDITS ===
export class BookmarkService {
  private bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates and stores a new bookmark.
   *
   * @param data - The bookmark data containing a required URL and optional title and tags.
   * @returns The newly created bookmark with generated ID and creation timestamp.
   * @throws {DuplicateBookmarkError} If a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example Domain',
   *   tags: ['example', 'web'],
   * });
   * console.log(bookmark.id);
   * ```
   */
  create(data: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === data.url) {
        throw new DuplicateBookmarkError(`Bookmark with URL "${data.url}" already exists`);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: data.url,
      title: data.title,
      tags: data.tags ? [...data.tags] : undefined,
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The unique string ID of the bookmark.
   * @returns The matching bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('e26c11a2-4a7b-4be5-94cf-e48f76024d26');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted by creation date in descending order (newest first).
   *
   * @returns An array of all bookmarks sorted newest first.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * console.log(`Total bookmarks: ${allBookmarks.length}`);
   * ```
   */
  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated subset of bookmarks sorted by creation date descending.
   *
   * @param page - 1-based page number.
   * @param limit - Maximum number of items per page.
   * @returns A paginated result containing the page's bookmarks and pagination metadata.
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 10);
   * console.log(result.data);
   * console.log(result.pagination.totalPages);
   * ```
   */
  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Updates the title and/or tags of an existing bookmark. URL cannot be changed.
   *
   * @param id - The unique identifier of the bookmark to update.
   * @param data - The fields to update (optional title and/or tags).
   * @returns The updated bookmark if found, or undefined if the bookmark does not exist.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('e26c11a2-4a7b-4be5-94cf-e48f76024d26', {
   *   title: 'Updated Title',
   *   tags: ['new-tag'],
   * });
   * ```
   */
  update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by title (case-insensitive substring) and tags (exact match).
   *
   * @param query - The search query term.
   * @returns An array of matching bookmarks sorted newest first.
   *
   * @example
   * ```ts
   * const matches = bookmarkService.search('typescript');
   * matches.forEach((b) => console.log(b.title));
   * ```
   */
  search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The unique identifier of the bookmark to delete.
   * @returns True if the bookmark was found and deleted, false if not found.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('e26c11a2-4a7b-4be5-94cf-e48f76024d26');
   * if (deleted) {
   *   console.log('Bookmark removed');
   * }
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Removes all bookmarks from memory.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * console.log(bookmarkService.getAll().length); // 0
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

