export const bookmarksRouter = Router();

/**
 * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
 *
 * @param req - Express request with optional `page` and `limit` query parameters.
 * @param res - Express response sending paginated bookmark results.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks?page=1&limit=20
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
}

/**
 * Handles GET /api/v1/bookmarks/search - Searches bookmarks by title or tags.
 *
 * @param req - Express request with required non-empty `q` query parameter.
 * @param res - Express response sending matching bookmarks or 400 error.
 * @returns Void.
 *
 * @example
 * ```ts
 * // GET /api/v1/bookmarks/search?q=typescript
 * bookmarksRouter.get('/search', searchBookmarksHandler);
 * ```
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const rawQ = getQueryString(req.query.q);
  if (rawQ === undefined || rawQ.trim() === '') {
    res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
    return;
  }

